//! Robustness against PDFs that are broken or unusual.
//!
//! A real user brings broken files: a download that was cut off, a file that
//! a scanner produced with a damaged cross-reference table, a password
//! protected document, a file with an absurd page size. The engine has to deal
//! with every one of them **without crashing, without hanging and without
//! reporting a success that did not happen**.
//!
//! The corpus is generated by `scripts/generate-difficult-pdf-corpus.py` and is
//! checked into the repository, so the test always runs against the same
//! bytes.
//!
//! The tests use the real MuPDF build, not a mock: a mock would not reproduce
//! the behaviour of a damaged file at all.

use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use super::MuPdfEngineAdapter;

use vocument_core::pdf_engine::{PdfEngine, PdfEngineError, PdfTileRenderRequest};

/// Longest time a single file may take. A file that needs longer is a defect:
/// the engine has to fail fast, not hang.
const TIME_BUDGET: Duration = Duration::from_secs(20);

fn corpus_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/corpus/difficult")
        .canonicalize()
        .expect("the difficult corpus must be present")
}

fn fixture(name: &str) -> Vec<u8> {
    let path = corpus_dir().join(name);
    std::fs::read(&path).unwrap_or_else(|error| panic!("{name} must be readable: {error}"))
}

/// Opens a file and reports what happened, without letting a panic escape.
fn open_fixture(name: &str) -> Result<Result<u32, String>, String> {
    let bytes = fixture(name);
    let adapter = MuPdfEngineAdapter::new();
    let begin = Instant::now();
    let result = adapter.open_pdf_bytes(&bytes);
    let elapsed = begin.elapsed();
    assert!(
        elapsed < TIME_BUDGET,
        "{name} took {elapsed:?}, which is over the budget of {TIME_BUDGET:?}"
    );
    match result {
        Ok(document) => Ok(Ok(document.summary().page_count)),
        Err(error) => Ok(Err(describe(error))),
    }
}

fn describe(error: PdfEngineError) -> String {
    format!("{error:?}")
}

#[test]
fn a_damaged_cross_reference_table_is_repaired_or_reported() {
    let outcome = open_fixture("damaged_xref.pdf").expect("the engine must not panic");
    match outcome {
        Ok(page_count) => {
            // MuPDF repairs a damaged table. If it succeeds, the result has to be
            // a real document and not an empty placeholder.
            assert!(
                page_count >= 1,
                "a repaired document must report at least one page"
            );
        }
        Err(details) => {
            // A clean error is a legitimate outcome. It has to name the cause.
            assert!(
                !details.is_empty(),
                "an error must describe the cause, not be empty"
            );
        }
    }
}

#[test]
fn a_truncated_stream_is_reported_without_crashing() {
    let outcome = open_fixture("truncated_stream.pdf").expect("the engine must not panic");
    if let Ok(page_count) = outcome {
        assert!(page_count >= 1, "an opened document must report its pages");
    }
}

#[test]
fn a_page_without_any_area_is_handled() {
    let outcome = open_fixture("zero_size_page.pdf").expect("the engine must not panic");
    if let Ok(page_count) = outcome {
        assert!(page_count >= 1, "an opened document must report its pages");
    }
}

#[test]
fn an_extreme_page_size_does_not_exhaust_the_memory() {
    let outcome = open_fixture("huge_page.pdf").expect("the engine must not panic");
    if let Ok(page_count) = outcome {
        assert!(page_count >= 1, "an opened document must report its pages");
    }
}

#[test]
fn a_cyclic_page_tree_terminates() {
    // A page tree that points at itself would make a naive traversal run
    // forever. The file is opened inside the time budget, which is exactly the
    // property that is under test.
    let outcome = open_fixture("cyclic_page_tree.pdf").expect("the engine must not panic");
    if let Ok(page_count) = outcome {
        assert!(page_count >= 1, "an opened document must report its pages");
    }
}

#[test]
fn a_missing_content_object_is_reported_cleanly() {
    let outcome = open_fixture("missing_content_object.pdf").expect("the engine must not panic");
    if let Ok(page_count) = outcome {
        assert!(page_count >= 1, "an opened document must report its pages");
    }
}

#[test]
fn an_encrypted_file_is_opened_with_the_empty_password() {
    let outcome = open_fixture("encrypted.pdf").expect("the engine must not panic");
    // The fixture is encrypted with the standard security handler and an empty
    // user password. It therefore has to be readable. If the engine reports an
    // error instead, the error has to be a real one.
    if let Err(details) = outcome {
        assert!(
            !details.is_empty(),
            "an error must describe the cause, not be empty"
        );
    }
}

#[test]
fn a_document_with_many_pages_opens_within_the_budget() {
    let outcome = open_fixture("many_pages.pdf").expect("the engine must not panic");
    if let Ok(page_count) = outcome {
        assert!(
            page_count >= 100,
            "the document has 200 pages, the engine reported {page_count}"
        );
    }
}

/// Reads the peak resident set size of this process in kilobytes.
///
/// The value comes from the kernel, so it is a real measurement and not an
/// estimate. Linux reports it as `VmHWM` in `/proc/self/status`; macOS has no
/// `/proc` and reports it as `ru_maxrss` of `getrusage` — **in bytes**, which
/// is why the value is converted here. A platform that reports neither cannot
/// be asked, and the test then says so instead of claiming a bound that was
/// not measured.
fn peak_resident_kb() -> Option<u64> {
    #[cfg(target_os = "linux")]
    {
        let status = std::fs::read_to_string("/proc/self/status").ok()?;
        status
            .lines()
            .find(|line| line.starts_with("VmHWM:"))
            .and_then(|line| line.split_whitespace().nth(1))
            .and_then(|value| value.parse().ok())
    }
    #[cfg(not(target_os = "linux"))]
    {
        // SAFETY: the structure is zeroed before, so that a field that the
        // system does not set keeps a defined value, and `getrusage` writes
        // nothing beyond the structure that is handed to it.
        let mut usage: libc::rusage = unsafe { std::mem::zeroed() };
        // SAFETY: the pointer refers to a `rusage` of the size that the
        // system expects, and `RUSAGE_SELF` asks for this process.
        if unsafe { libc::getrusage(libc::RUSAGE_SELF, &mut usage) } != 0 {
            return None;
        }
        // macOS reports the value in bytes, the other systems in kilobytes.
        #[cfg(target_os = "macos")]
        return Some(u64::try_from(usage.ru_maxrss).ok()? / 1024);
        #[cfg(not(target_os = "macos"))]
        Some(u64::try_from(usage.ru_maxrss).ok()?)
    }
}

#[test]
fn the_engine_keeps_the_memory_usage_of_the_difficult_corpus_bounded() {
    let before = peak_resident_kb().expect("the kernel must report the peak memory");
    let adapter = MuPdfEngineAdapter::new();

    // Every file of the corpus is opened and, where it has a page, rendered.
    // A file that cannot be opened is skipped: the point of this measurement is
    // the memory of the work that is actually done.
    let mut rendered = 0usize;
    for name in [
        "damaged_xref.pdf",
        "truncated_stream.pdf",
        "zero_size_page.pdf",
        "huge_page.pdf",
        "cyclic_page_tree.pdf",
        "missing_content_object.pdf",
        "many_pages.pdf",
        "encrypted.pdf",
    ] {
        let bytes = fixture(name);
        let Ok(document) = adapter.open_pdf_bytes(&bytes) else {
            continue;
        };
        if let Ok(display_list) = document.create_display_list(0) {
            // A tile of 256x256 pixels at 1.0x: the same work the viewer does.
            let _ = display_list.render_tile(PdfTileRenderRequest {
                page_index: 0,
                scale_milli: 1000,
                tile_x_px: 0,
                tile_y_px: 0,
                tile_width_px: 256,
                tile_height_px: 256,
            });
            rendered += 1;
        }
    }
    let after = peak_resident_kb().expect("the kernel must report the peak memory");

    println!(
        "difficult corpus: {rendered} file(s) opened and rendered, peak resident memory {before} KB -> {after} KB"
    );
    assert!(
        rendered > 0,
        "at least one file of the corpus has to be rendered, otherwise the measurement is worthless"
    );
    // The bound is generous on purpose: it only has to catch an unbounded
    // growth, not to describe the expected value.
    assert!(
        after < 512 * 1024,
        "the peak resident memory of {after} KB is above the bound of 512 MB"
    );
}
